package it.polimi.ingsoft.mesos.server.controller.command;

/**
 * Internal queue command used when an existing session disconnects.
 *
 * <p>This command is generated by server lifecycle code, not by a client
 * payload. It carries only the {@code sessionId}; the controller that consumes
 * it is responsible for asking {@code ServerSessionRegistry} for the listener,
 * nickname, and any model object it needs.
 *
 * <p>Keeping only the session id avoids passing stale duplicated state through
 * the queue. The disconnect cleanup must therefore happen after the command has
 * been processed, while the registry still knows the session.
 */
public class SystemDisconnectCommand implements QueuedCommand {
    private final String sessionId;

    public SystemDisconnectCommand(String sessionId) {
        this.sessionId = sessionId;
    }

    @Override
    public String getSessionId() {
        return this.sessionId;
    }
}
